static int parse_long(const char *s, long *out)
{
    char *endptr;
    errno = 0;
    long val = strtol(s, &endptr, 10);
    if (errno != 0) return -1;
    if (endptr == s) return -1;
    if (*endptr != '\0') return -1;
    *out = val;
    return 0;
}

